from collections import Counter

def dup_rates(notices, duplicate_ids):
    total = Counter(n['source'] for n in notices)
    dups = Counter(n['source'] for n in notices if n['notice_id'] in duplicate_ids)
    return {s: dups[s] / total[s] for s in total}

