FIELDS = ['title', 'buyer', 'cpv', 'deadline', 'estimated_value', 'lots']

def canonical(group):
    ordered = sorted(group, key=lambda n: n['published'], reverse=True)
    record = {}
    for field in FIELDS:
        record[field] = next((n[field] for n in ordered if n.get(field)), None)
    return record

