import base64

def encode_cursor(offset: int) -> str:
    return base64.urlsafe_b64encode(str(offset).encode()).decode()

def page(rows, cursor=None, size=100):
    start = int(base64.urlsafe_b64decode(cursor)) if cursor else 0
    nxt = encode_cursor(start + size) if start + size < len(rows) else None
    return {'items': rows[start:start + size], 'next': nxt}
